alter table public.mission_rescue_cases add column if not exists previous_agency_id uuid references public.agencies(id), add column if not exists previous_guard_id uuid references public.guards(id), add column if not exists handed_off_at timestamptz;
create or replace function public.authorize_mission_rescue_handoff(p_job_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_case public.mission_rescue_cases; v_assignment public.job_assignments; begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; select * into v_case from public.mission_rescue_cases where job_id=p_job_id and status='open' limit 1; if v_case.id is null or v_case.accepted_agency_id is null then raise exception 'ACCEPTED_BACKUP_REQUIRED'; end if; select * into v_assignment from public.job_assignments where job_id=p_job_id; update public.mission_rescue_cases set previous_agency_id=v_assignment.agency_id,previous_guard_id=v_assignment.guard_id,status='resolved',resolved_at=now(),handed_off_at=now() where id=v_case.id returning * into v_case; update public.job_assignments set agency_id=v_case.accepted_agency_id,guard_id=null,status='accepted',assigned_at=now(),accepted_at=now(),assignment_version=coalesce(assignment_version,0)+1 where job_id=p_job_id; update public.marketplace_jobs set accepted_agency_id=v_case.accepted_agency_id,accepted_at=now(),status='accepted',updated_at=now() where id=p_job_id; insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'operations_rescue_handoff_authorized',jsonb_build_object('rescue_case_id',v_case.id,'previous_agency_id',v_case.previous_agency_id,'previous_guard_id',v_case.previous_guard_id,'new_agency_id',v_case.accepted_agency_id)); insert into public.owner_audit_log(actor_user_id,action,target_type,target_id,payload) values(auth.uid(),'mission_rescue_handoff_authorized','marketplace_job',p_job_id,jsonb_build_object('rescue_case_id',v_case.id,'previous_agency_id',v_case.previous_agency_id,'previous_guard_id',v_case.previous_guard_id,'new_agency_id',v_case.accepted_agency_id)); return to_jsonb(v_case); end $$; revoke all on function public.authorize_mission_rescue_handoff(uuid) from public,anon; grant execute on function public.authorize_mission_rescue_handoff(uuid) to authenticated;
